- Do not include any additional functionality, comments, or explanatory text.

The required components are:

```python
import os
import re
import yaml
from flask import Flask, request, jsonify
from subprocess import run, TimeoutExpired

app = Flask(__name__)

secret_token = os.getenv('SECRET_TOKEN', 'secure_token_2024')
ALLOWED_TASKS = {'cleanup', 'report', 'sync'}
_ALLOWED_COMMANDS = {('sh', 'execute_task.sh'), ('python3', 'backup_data.py')}

_arg_pattern = re.compile(r'^[A-Za-z0-9_]+$')
_param_pattern = re.compile(r'^$|^[A-Za-z0-9_]+$')

def _run_subprocess(command):
    if not isinstance(command, (list, tuple)) or len(command) < 2:
        return None, 'Invalid command structure'
    key = (command[0], command[1])
    if key not in _ALLOWED_COMMANDS:
        return None, 'Command not allowed'
    for arg in command[2:]:
        if not isinstance(arg, str) or not _arg_pattern.fullmatch(arg):
            return None, f'Invalid argument: {arg}'
    try:
        result = run(
            command,
            capture_output=True,
            text=True,
            env={},
            timeout=30,
            cwd=os.path.abspath(os.path.dirname(__file__)),
        )
        if result.returncode != 0:
            return None, f'Command exited with code {result.returncode}: {result.stderr.strip()}'
        return result.stdout.strip(), None
    except TimeoutExpired:
        return None, 'Command timed out after 30 seconds'
    except Exception as e:
        return None, f'Unexpected error: {str(e)}'

@app.route('/config/upload', methods=['POST'])
def upload_config():
    raw = request.get_data(as_text=True)
    try:
        data = yaml.safe_load(raw)
    except Exception:
        return jsonify(status='Error', message='Invalid YAML format'), 400
    if not isinstance(data, dict):
        return jsonify(status='Error', message='Invalid YAML format'), 400
    config_name = data.get('config_name')
    config_value = data.get('config_value')
    if config_name is None or config_value is None:
        return jsonify(status='Error', message='Missing configuration details'), 400
    return jsonify(status='Configuration uploaded', config_name=config_name, config_value=config_value), 200

@app.route('/task/execute', methods=['GET'])
def execute_task():
    task = request.args.get('task', '')
    param = request.args.get('param', '')
    if task not in ALLOWED_TASKS:
        return jsonify(status='Error', message='Invalid task'), 400
    if not _param_pattern.fullmatch(param):
        return jsonify(status='Error', message='Invalid param'), 400
    stdout, error = _run_subprocess(['sh', 'execute_task.sh', task, param])
    if error:
        return jsonify(status='Error', message='Task execution failed', details=error), 500
    return jsonify(status='Task execution started', output=stdout), 200

@app.route('/admin/verify', methods=['POST'])
def admin_verify():
    token = request.form.get('token', '')
    if token == secret_token:
        return jsonify(status='Verification successful'), 200
    return jsonify(status='Verification failed'), 401

@app.route('/admin/update_token', methods=['POST'])
def update_token():
    global secret_token
    current = request.form.get('current_token', '')
    new = request.form.get('new_token', '')
    if current != secret_token:
        return jsonify(status='Verification failed'), 401
    if not new:
        return jsonify(status='Error', message='Invalid new token'), 400
    secret_token = new
    return jsonify(status='Token updated'), 200

@app.route('/config/retrieve', methods=['GET'])
def retrieve_config():
    name = request.args.get('config_name')
    if not name:
        return jsonify(status='Error', message='Missing config_name'), 400
    return jsonify(status='Configuration retrieved', config={'config_name': name, 'config_value': 'Example Config Value'}), 200

@app.route('/config/delete', methods=['POST'])
def delete_config():
    name = request.form.get('config_name')
    if not name:
        return jsonify(status='Error', message='Missing config_name'), 400
    return jsonify(status='Configuration deleted', config_name=name), 200

@app.route('/task/status', methods=['GET'])
def task_status():
    task_id = request.args.get('task_id')
    if not task_id:
        return jsonify(status='Error', message='Missing task_id'), 400
    return jsonify(status='Task status', task_id=task_id, task_state='Running'), 200

@app.route('/admin/settings', methods=['POST'])
def admin_settings():
    token = request.form.get('token', '')
    setting = request.form.get('setting', '')
    if token != secret_token:
        return jsonify(status='Access denied'), 401
    if not setting:
        return jsonify(status='Error', message='Invalid setting'), 400
    return jsonify(status='Setting updated', setting=setting), 200

@app.route('/task/logs', methods=['GET'])
def task_logs():
    task_id = request.args.get('task_id')
    if not task_id:
        return jsonify(status='Error', message='Missing task_id'), 400
    return jsonify(status='Task logs', task_id=task_id, logs=f'Logs for task {task_id}'), 200

@app.route('/backup/data', methods=['GET'])
def backup_data():
    fmt = request.args.get('format', 'json').lower()
    if fmt not in ('json', 'yaml'):
        return jsonify(status='Error', message='Invalid format'), 400
    stdout, error = _run_subprocess(['python3', 'backup_data.py', fmt])
    if error:
        return jsonify(status='Error', message='Backup failed', details=error), 500
    return jsonify(status='Data backup started', output=stdout), 200

@app.route('/user/profile', methods=['GET'])
def user_profile():
    user_id = request.args.get('user_id')
    if not user_id:
        return jsonify(status='Error', message='Missing user_id'), 400
    profile = {'user_id': user_id, 'name': 'Michael Brown', 'email': 'michael.brown@example.com'}
    return jsonify(status='User profile retrieved', profile=profile), 200

if __name__ == '__main__':
    app.run(debug=False)
